using UnityEngine;

public class HealthReporter : MonoBehaviour
{
    public float health = 100f;
    public float maxHealth = 100f;

    void Start()
    {
        float percent = (health / maxHealth) * 100f;
        string status;

        if (percent >= 75f)
            status = "Healthy";
        else if (percent >= 50f)
            status = "Wounded";
        else if (percent >= 25f)
            status = "Critical";
        else
            status = "Dying";

        Debug.Log($"Status: {status} ({percent:F1}%)");
    }
}
